import json
from pathlib import Path

import jax
import jax.numpy as jnp
import numpy as np


def task_basic_reduce(inp_path: Path) -> np.ndarray:
    x = jnp.asarray(np.load(inp_path))
    return np.asarray(jnp.mean(x, axis=1))


def task_map_square(inp_path: Path) -> np.ndarray:
    x = jnp.asarray(np.load(inp_path))
    return np.asarray(jnp.square(x))


def task_grad_logistic(inp_path: Path) -> np.ndarray:
    data = np.load(inp_path)
    x = jnp.asarray(data["x"])
    y = jnp.asarray(data["y"])
    w = jnp.asarray(data["w"])

    def loss(w, x, y):
        z = jnp.dot(x, w)
        return jnp.mean(jnp.logaddexp(0.0, -y * z))

    grad_w = jax.grad(loss)(w, x, y)
    return np.asarray(grad_w)


def task_scan_rnn(inp_path: Path) -> np.ndarray:
    data = np.load(inp_path)
    seq = jnp.asarray(data["seq"])
    h0 = jnp.asarray(data["init"])
    wx = jnp.asarray(data["Wx"])
    wh = jnp.asarray(data["Wh"])
    b = jnp.asarray(data["b"])

    def step(h, x_t):
        h_next = jnp.tanh(jnp.dot(x_t, wx) + jnp.dot(h, wh) + b)
        return h_next, h_next

    _, hs = jax.lax.scan(step, h0, seq)
    return np.asarray(hs)


def task_jit_mlp(inp_path: Path) -> np.ndarray:
    data = np.load(inp_path)
    x = jnp.asarray(data["X"])
    w1 = jnp.asarray(data["W1"])
    b1 = jnp.asarray(data["b1"])
    w2 = jnp.asarray(data["W2"])
    b2 = jnp.asarray(data["b2"])

    def mlp(x, w1, b1, w2, b2):
        h = jnp.maximum(0.0, jnp.dot(x, w1) + b1)
        return jnp.dot(h, w2) + b2

    mlp_jit = jax.jit(mlp)
    y = mlp_jit(x, w1, b1, w2, b2)
    return np.asarray(y)


TASKS = {
    "basic_reduce": task_basic_reduce,
    "map_square": task_map_square,
    "grad_logistic": task_grad_logistic,
    "scan_rnn": task_scan_rnn,
    "jit_mlp": task_jit_mlp,
}


def main() -> None:
    base = Path("/app")
    problem_path = base / "problem.json"
    tasks = json.loads(problem_path.read_text())

    for task in tasks:
        task_id = task["id"]
        inp = base / task["input"]
        out = base / task["output"]
        if task_id not in TASKS:
            raise ValueError(f"Unknown task id: {task_id}")
        result = TASKS[task_id](inp)
        out.parent.mkdir(parents=True, exist_ok=True)
        np.save(out, result)


if __name__ == "__main__":
    main()
